189	// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
190	// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
191	func ListCheckpoints(ctx context.Context) ([]CheckpointInfo, error) {
192		repo, err := OpenRepository(ctx)
193		if err != nil {
194			return nil, fmt.Errorf("failed to open git repository: %w", err)
195		}
196	
197		// Warn (once per process) if metadata branches are disconnected
198		WarnIfMetadataDisconnected()
199	
200		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
201		ref, err := repo.Reference(refName, true)
202		if err != nil {
203			//nolint:nilerr // No sessions branch yet is expected, return empty list
204			return []CheckpointInfo{}, nil
205		}
206	
207		commit, err := repo.CommitObject(ref.Hash())
208		if err != nil {
209			return nil, fmt.Errorf("failed to get commit object: %w", err)
210		}
211	
212		tree, err := commit.Tree()
213		if err != nil {
214			return nil, fmt.Errorf("failed to get commit tree: %w", err)
215		}
216	
217		var checkpoints []CheckpointInfo
218	
219		// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
220		// The tree has 2-character directories (hex buckets)
221		for _, bucketEntry := range tree.Entries {
222			if bucketEntry.Mode != filemode.Dir {
223				continue
224			}
225			// Bucket should be 2 hex chars
226			if len(bucketEntry.Name) != 2 {
227				continue
228			}
229	
230			bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
231			if treeErr != nil {
232				continue
233			}
234	
235			// Each entry in the bucket is the remaining part of the checkpoint ID
236			for _, checkpointEntry := range bucketTree.Entries {
237				if checkpointEntry.Mode != filemode.Dir {
238					continue
239				}
240	
241				checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
242				if cpTreeErr != nil {
243					continue
244				}
245	
246				// Reconstruct checkpoint ID: <bucket><remaining>
247				checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
248				checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
249				if cpErr != nil {
250					// Skip invalid checkpoint IDs
251					continue
252				}
253	
254				info := CheckpointInfo{
255					CheckpointID: checkpointID,
256				}
257	
258				// Get details from metadata file (CheckpointSummary format)
259				if summary, ok := decodeSummaryLiteFromTree(checkpointTree); ok {
260					info.CheckpointsCount = summary.CheckpointsCount
261					info.FilesTouched = summary.FilesTouched
262					info.SessionCount = len(summary.Sessions)
263	
264					// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
265					for i, sessionPaths := range summary.Sessions {
266						if sessionPaths.Metadata == "" {
267							continue
268						}
269						// SessionFilePaths contains absolute paths with leading "/"
270						// Strip the leading "/" for tree.File() which expects paths without leading slash
271						sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
272						sessionMeta, sErr := decodeSessionMetadataLite(tree, sessionMetadataPath)
273						if sErr != nil {
274							continue
275						}
276						info.SessionIDs = append(info.SessionIDs, sessionMeta.SessionID)
277						// Use first session's metadata for Agent, SessionID, CreatedAt
278						if i == 0 {
279							info.Agent = sessionMeta.Agent
280							info.SessionID = sessionMeta.SessionID
281							info.CreatedAt = sessionMeta.CreatedAt
282							info.IsTask = sessionMeta.IsTask
283							info.ToolUseID = sessionMeta.ToolUseID
284						}
285					}
286				}
287	
288				checkpoints = append(checkpoints, info)
289			}
290		}
291	
292		// Sort by time (most recent first)
293		sort.Slice(checkpoints, func(i, j int) bool {
294			return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
295		})
296	
297		return checkpoints, nil
298	}
