307	// isProtectedPath returns true if relPath is inside a directory that should
308	// never be modified or deleted during rewind or other destructive operations.
309	// Protected directories include git internals, entire metadata, and all
310	// registered agent config directories.
311	func isProtectedPath(relPath string) bool {
312		for _, dir := range protectedDirs() {
313			if paths.IsSubpath(dir, relPath) {
314				return true
315			}
316		}
317		return false
318	}
