320	// protectedDirs returns the list of directories to protect. This combines
321	// static infrastructure dirs with agent-reported dirs from the registry.
322	// The result is cached via sync.Once since it's called per-file when filtering untracked files.
323	//
324	// NOTE: The cache is never invalidated. In production this is fine (the agent registry
325	// is populated at init time and never changes). However, tests that mutate the agent
326	// registry after the first call to protectedDirs/isProtectedPath will see stale results.
327	// If you need to test isProtectedPath with a custom registry, either:
328	//   - run those tests in a separate process, or
329	//   - call resetProtectedDirsForTest() to clear the cache.
330	func protectedDirs() []string {
331		protectedDirsOnce.Do(func() {
332			protectedDirsCache = append([]string{gitDir, entireDir}, agent.AllProtectedDirs()...)
333		})
334		return protectedDirsCache
335	}
