   189	// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
   190	// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   191	func ListCheckpoints(ctx context.Context) ([]CheckpointInfo, error) {
   192		repo, err := OpenRepository(ctx)
   193		if err != nil {
   194			return nil, fmt.Errorf("failed to open git repository: %w", err)
   195		}
