   203			//nolint:nilerr // No sessions branch yet is expected, return empty list
   204			return []CheckpointInfo{}, nil
   205		}
   206	
   207		commit, err := repo.CommitObject(ref.Hash())
   208		if err != nil {
   209			return nil, fmt.Errorf("failed to get commit object: %w", err)
   210		}
   211	
   212		tree, err := commit.Tree()
   213		if err != nil {
   214			return nil, fmt.Errorf("failed to get commit tree: %w", err)
   215		}
   216	
   217		var checkpoints []CheckpointInfo
   218	
   219		// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   220		// The tree has 2-character directories (hex buckets)
   221		for _, bucketEntry := range tree.Entries {
   222			if bucketEntry.Mode != filemode.Dir {
   223				continue
   224			}
   225			// Bucket should be 2 hex chars
   226			if len(bucketEntry.Name) != 2 {
   227				continue
   228			}
   229	
   230			bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
   231			if treeErr != nil {
   232				continue
   233			}
   234	
   235			// Each entry in the bucket is the remaining part of the checkpoint ID
   236			for _, checkpointEntry := range bucketTree.Entries {
   237				if checkpointEntry.Mode != filemode.Dir {
   238					continue
   239				}
   240	
   241				checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
   242				if cpTreeErr != nil {
   243					continue
   244				}
   245	
   246				// Reconstruct checkpoint ID: <bucket><remaining>
   247				checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   248				checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
   249				if cpErr != nil {
