620	// RestoreLogsOnly restores session logs from a logs-only rewind point.
621	// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
622	// Does not modify the working directory.
623	// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
624	// If force is false, prompts for confirmation when local logs have newer timestamps.
625	// Returns info about each restored session so callers can print correct per-session resume commands.
626	func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, w, errW io.Writer, point RewindPoint, force bool) ([]RestoredSession, error) {
627		if !point.IsLogsOnly {
628			return nil, errors.New("not a logs-only rewind point")
629		}
630	
631		if point.CheckpointID.IsEmpty() {
632			return nil, errors.New("missing checkpoint ID")
633		}
634	
635		// Resolve which store has this checkpoint. Try v2 first when enabled.
636		// The chosen reader is used for all subsequent reads (summary + session content)
637		// to avoid mixed v1/v2 reads. No per-session fallback to v1: during dual-write,
638		// both stores receive the same data, so if v2 has the summary it also has the
639		// transcripts on /full/* refs.
640		var reader committedReader
641		var summary *cpkg.CheckpointSummary
642	
643		if settings.IsCheckpointsV2Enabled(ctx) {
644			v2Store, v2Err := s.getV2CheckpointStore(ctx)
645			if v2Err == nil {
646				v2Summary, readErr := v2Store.ReadCommitted(ctx, point.CheckpointID)
647				if readErr != nil {
648					logging.Debug(ctx, "v2 ReadCommitted failed, falling back to v1",
649						slog.String("checkpoint_id", string(point.CheckpointID)),
650						slog.String("error", readErr.Error()),
651					)
652				} else if v2Summary != nil {
653					reader = v2Store
654					summary = v2Summary
655				}
656			}
657		}
658	
659		if summary == nil {
660			v1Store, err := s.getCheckpointStore()
661			if err != nil {
662				return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
663			}
664			summary, err = v1Store.ReadCommitted(ctx, point.CheckpointID)
665			if err != nil {
666				return nil, fmt.Errorf("failed to read checkpoint: %w", err)
667			}
668			reader = v1Store
669		}
670		if summary == nil {
671			return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
672		}
673	
