+
+const defaultFetchTimeout = 2 * time.Minute
+
+// FallbackFunc runs when the primary fetch fails.
+// Returning nil marks the fetch as recovered.
+type FallbackFunc func(context.Context, error) error
+
+// Option configures a Fetch operation.
+type Option func(*fetchConfig) error
+
+type fetchMode int
+
+const (
+	fetchModeUnknown fetchMode = iota
+	fetchModeRef
+	fetchModeBlobs
+)
+
+type fetchConfig struct {
+	mode                fetchMode
+	target              string
+	timeout             time.Duration
+	sourceRef           plumbing.ReferenceName
+	destinationRef      plumbing.ReferenceName
+	advanceLocalRef     plumbing.ReferenceName
+	promoteToRef        plumbing.ReferenceName
+	promoteLabel        string
+	label               string
+	hashes              []plumbing.Hash
+	shallow             bool
+	noWriteFetchHead    bool
+	disablePrompt       bool
+	resolveTarget       bool
+	appendFilterArgs    bool
+	noTags              bool
+	fallback            FallbackFunc
+}
+
+func defaultConfig() fetchConfig {
+	return fetchConfig{
+		target:        "origin",
+		timeout:       defaultFetchTimeout,
+		resolveTarget: true,
+		appendFilterArgs: true,
+		noTags:        true,
+	}
+}
+
+func (c fetchConfig) validate() error {
+	switch c.mode {
+	case fetchModeRef:
+		if c.sourceRef == "" {
+			return errors.New("fetch source ref is required")
+		}
+		if c.destinationRef == "" {
+			return errors.New("fetch destination ref is required")
+		}
+	case fetchModeBlobs:
+		if len(c.hashes) == 0 {
+			return errors.New("at least one blob hash is required")
+		}
+		if c.destinationRef != "" || c.advanceLocalRef != "" || c.promoteToRef != "" {
+			return errors.New("blob fetches cannot update refs")
+		}
+		if c.shallow {
+			return errors.New("blob fetches cannot be shallow")
+		}
+	default:
+		return errors.New("fetch mode is required")
+	}
+
+	if c.timeout <= 0 {
+		return errors.New("fetch timeout must be positive")
+	}
+
+	if c.advanceLocalRef != "" && c.promoteToRef != "" {
+		return errors.New("advance and promote post-fetch actions are mutually exclusive")
+	}
+
+	if c.promoteToRef != "" && c.promoteLabel == "" {
+		return errors.New("promote label is required when promoting a fetched ref")
+	}
+
+	return nil
+}
+
+func (c fetchConfig) errorLabel() string {
+	if c.label != "" {
+		return c.label
+	}
+
+	switch c.mode {
+	case fetchModeBlobs:
+		return "blob objects"
+	case fetchModeRef:
+		if c.promoteLabel != "" {
+			return c.promoteLabel
+		}
+		if c.sourceRef != "" {
+			return string(c.sourceRef)
+		}
+	}
