+		c.mode = fetchModeRef
+		c.sourceRef = plumbing.ReferenceName("refs/heads/" + paths.MetadataBranchName)
+		c.label = paths.MetadataBranchName
+		return nil
+	}
+}
+
+// WithV2Main configures the fetch for the v2 /main ref.
+func WithV2Main() Option {
+	return func(c *fetchConfig) error {
+		c.mode = fetchModeRef
+		c.sourceRef = plumbing.ReferenceName(paths.V2MainRefName)
+		c.label = "v2 /main"
+		return nil
+	}
+}
+
+// WithBlobHashes configures the fetch to download specific objects by hash.
+func WithBlobHashes(hashes []plumbing.Hash) Option {
+	return func(c *fetchConfig) error {
+		c.mode = fetchModeBlobs
+		c.hashes = append([]plumbing.Hash(nil), hashes...)
+		c.appendFilterArgs = false
