+
+// WithDestinationRef sets the refspec destination for ref fetches.
+func WithDestinationRef(ref plumbing.ReferenceName) Option {
+	return func(c *fetchConfig) error {
+		if ref == "" {
+			return errors.New("destination ref cannot be empty")
+		}
+		c.destinationRef = ref
+		return nil
+	}
+}
+
+// WithAdvanceLocalRef safely advances a local ref to the fetched destination ref.
+func WithAdvanceLocalRef(ref plumbing.ReferenceName) Option {
+	return func(c *fetchConfig) error {
+		if ref == "" {
+			return errors.New("local ref cannot be empty")
+		}
+		c.advanceLocalRef = ref
+		return nil
+	}
+}
+
+// WithPromoteTo promotes the fetched destination ref to another ref after fetch.
+func WithPromoteTo(ref plumbing.ReferenceName, label string) Option {
+	return func(c *fetchConfig) error {
+		if ref == "" {
+			return errors.New("promote ref cannot be empty")
+		}
+		if strings.TrimSpace(label) == "" {
+			return errors.New("promote label cannot be empty")
+		}
+		c.promoteToRef = ref
+		c.promoteLabel = label
+		return nil
+	}
+}
+
+// WithNoWriteFetchHead adds --no-write-fetch-head.
+func WithNoWriteFetchHead() Option {
+	return func(c *fetchConfig) error {
+		c.noWriteFetchHead = true
+		return nil
+	}
