package remote

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/strategy"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

const defaultFetchTimeout = 2 * time.Minute

// FallbackFunc runs when the primary fetch fails.
// Returning nil marks the fetch as recovered.
type FallbackFunc func(context.Context, error) error

// Option configures a Fetch operation.
type Option func(*fetchConfig) error

type fetchMode int

const (
	fetchModeUnknown fetchMode = iota
	fetchModeRef
	fetchModeBlobs
)

type fetchConfig struct {
	mode                fetchMode
	target              string
	timeout             time.Duration
	sourceRef           plumbing.ReferenceName
	destinationRef      plumbing.ReferenceName
	advanceLocalRef     plumbing.ReferenceName
	promoteToRef        plumbing.ReferenceName
	promoteLabel        string
	label               string
	hashes              []plumbing.Hash
	shallow             bool
	noWriteFetchHead    bool
	disablePrompt       bool
	resolveTarget       bool
	appendFilterArgs    bool
	noTags              bool
	fallback            FallbackFunc
}

func defaultConfig() fetchConfig {
	return fetchConfig{
		target:        "origin",
		timeout:       defaultFetchTimeout,
		resolveTarget: true,
		appendFilterArgs: true,
		noTags:        true,
	}
}

func (c fetchConfig) validate() error {
	switch c.mode {
	case fetchModeRef:
		if c.sourceRef == "" {
			return errors.New("fetch source ref is required")
		}
		if c.destinationRef == "" {
			return errors.New("fetch destination ref is required")
		}
	case fetchModeBlobs:
		if len(c.hashes) == 0 {
			return errors.New("at least one blob hash is required")
		}
		if c.destinationRef != "" || c.advanceLocalRef != "" || c.promoteToRef != "" {
			return errors.New("blob fetches cannot update refs")
		}
		if c.shallow {
			return errors.New("blob fetches cannot be shallow")
		}
	default:
		return errors.New("fetch mode is required")
	}

	if c.timeout <= 0 {
		return errors.New("fetch timeout must be positive")
	}

	if c.advanceLocalRef != "" && c.promoteToRef != "" {
		return errors.New("advance and promote post-fetch actions are mutually exclusive")
	}

	if c.promoteToRef != "" && c.promoteLabel == "" {
		return errors.New("promote label is required when promoting a fetched ref")
	}

	return nil
}

func (c fetchConfig) errorLabel() string {
	if c.label != "" {
		return c.label
	}

	switch c.mode {
	case fetchModeBlobs:
		return "blob objects"
	case fetchModeRef:
		if c.promoteLabel != "" {
			return c.promoteLabel
		}
		if c.sourceRef != "" {
			return string(c.sourceRef)
		}
	}

	return "checkpoint data"
}

// WithTarget sets the git fetch target. This can be a remote name or URL.
func WithTarget(target string) Option {
	return func(c *fetchConfig) error {
		if strings.TrimSpace(target) == "" {
			return errors.New("fetch target cannot be empty")
		}
		c.target = target
		return nil
	}
}

// WithTimeout sets the fetch timeout.
func WithTimeout(timeout time.Duration) Option {
	return func(c *fetchConfig) error {
		if timeout <= 0 {
			return errors.New("fetch timeout must be positive")
		}
		c.timeout = timeout
		return nil
	}
}

// WithV1Metadata configures the fetch for the v1 metadata branch.
func WithV1Metadata() Option {
	return func(c *fetchConfig) error {
		c.mode = fetchModeRef
		c.sourceRef = plumbing.ReferenceName("refs/heads/" + paths.MetadataBranchName)
		c.label = paths.MetadataBranchName
		return nil
	}
}

// WithV2Main configures the fetch for the v2 /main ref.
func WithV2Main() Option {
	return func(c *fetchConfig) error {
		c.mode = fetchModeRef
		c.sourceRef = plumbing.ReferenceName(paths.V2MainRefName)
		c.label = "v2 /main"
		return nil
	}
}

// WithBlobHashes configures the fetch to download specific objects by hash.
func WithBlobHashes(hashes []plumbing.Hash) Option {
	return func(c *fetchConfig) error {
		c.mode = fetchModeBlobs
		c.hashes = append([]plumbing.Hash(nil), hashes...)
		c.appendFilterArgs = false
		return nil
	}
}

// WithTreeOnly enables a shallow fetch for ref-based metadata reads.
func WithTreeOnly() Option {
	return func(c *fetchConfig) error {
		c.shallow = true
		return nil
	}
}

// WithDestinationRef sets the refspec destination for ref fetches.
func WithDestinationRef(ref plumbing.ReferenceName) Option {
	return func(c *fetchConfig) error {
		if ref == "" {
			return errors.New("destination ref cannot be empty")
		}
		c.destinationRef = ref
		return nil
	}
}

// WithAdvanceLocalRef safely advances a local ref to the fetched destination ref.
func WithAdvanceLocalRef(ref plumbing.ReferenceName) Option {
	return func(c *fetchConfig) error {
		if ref == "" {
			return errors.New("local ref cannot be empty")
		}
		c.advanceLocalRef = ref
		return nil
	}
}

// WithPromoteTo promotes the fetched destination ref to another ref after fetch.
func WithPromoteTo(ref plumbing.ReferenceName, label string) Option {
	return func(c *fetchConfig) error {
		if ref == "" {
			return errors.New("promote ref cannot be empty")
		}
		if strings.TrimSpace(label) == "" {
			return errors.New("promote label cannot be empty")
		}
		c.promoteToRef = ref
		c.promoteLabel = label
		return nil
	}
}

// WithNoWriteFetchHead adds --no-write-fetch-head.
func WithNoWriteFetchHead() Option {
	return func(c *fetchConfig) error {
		c.noWriteFetchHead = true
		return nil
	}
}

// WithDisableTerminalPrompt disables git terminal prompting for the fetch command.
func WithDisableTerminalPrompt() Option {
	return func(c *fetchConfig) error {
		c.disablePrompt = true
		return nil
	}
}

// WithFallback registers a fallback for failed fetches.
func WithFallback(fn FallbackFunc) Option {
	return func(c *fetchConfig) error {
		if fn == nil {
			return errors.New("fallback cannot be nil")
		}
		c.fallback = fn
		return nil
	}
}

type gitRunner func(context.Context, string, []string, []string) ([]byte, error)
type openRepoFunc func(context.Context) (*git.Repository, error)
type advanceRefFunc func(context.Context, *git.Repository, plumbing.ReferenceName, plumbing.Hash) error
type promoteRefFunc func(context.Context, plumbing.ReferenceName, plumbing.ReferenceName, string) error
type resolveTargetFunc func(context.Context, string) (string, error)
type appendFilterArgsFunc func(context.Context, []string) []string

// Fetcher performs checkpoint-related git fetches.
type Fetcher struct {
	runGit            gitRunner
	openRepo          openRepoFunc
	advanceLocalRef   advanceRefFunc
	promoteFetchedRef promoteRefFunc
	resolveTarget     resolveTargetFunc
	appendFilterArgs  appendFilterArgsFunc
}

// New returns a Fetcher with production defaults.
func New() *Fetcher {
	return &Fetcher{
		runGit:            defaultRunGit,
		openRepo:          defaultOpenRepository,
		advanceLocalRef:   strategy.SafelyAdvanceLocalRef,
		promoteFetchedRef: strategy.PromoteTmpRefSafely,
		resolveTarget:     strategy.ResolveFetchTarget,
		appendFilterArgs:  strategy.AppendFetchFilterArgs,
	}
}

// Fetch executes a checkpoint fetch using functional options.
func (f *Fetcher) Fetch(ctx context.Context, opts ...Option) error {
	if f == nil {
		f = New()
	}

	cfg := defaultConfig()
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		if err := opt(&cfg); err != nil {
			return err
		}
	}
	if err := cfg.validate(); err != nil {
		return err
	}

	fetchCtx, cancel := context.WithTimeout(ctx, cfg.timeout)
	defer cancel()

	target := cfg.target
	if cfg.resolveTarget {
		resolved, err := f.resolveTarget(fetchCtx, cfg.target)
		if err != nil {
			return fmt.Errorf("resolve fetch target: %w", err)
		}
		target = resolved
	}

	args := buildFetchArgs(fetchCtx, f.appendFilterArgs, cfg, target)
	output, err := f.runGit(fetchCtx, target, args, cfg.extraEnv())
	if err != nil {
		fetchErr := formatFetchError(fetchCtx, cfg, target, output, err)
		if cfg.fallback == nil {
			return fetchErr
		}
		if fallbackErr := cfg.fallback(fetchCtx, fetchErr); fallbackErr != nil {
			return fmt.Errorf("%w; fallback failed: %w", fetchErr, fallbackErr)
		}
		return nil
	}

	return f.postFetch(fetchCtx, cfg)
}

func buildFetchArgs(ctx context.Context, appendFilterArgs appendFilterArgsFunc, cfg fetchConfig, target string) []string {
	args := []string{"fetch"}
	if cfg.noTags {
		args = append(args, "--no-tags")
	}
	if cfg.noWriteFetchHead {
		args = append(args, "--no-write-fetch-head")
	}
	if cfg.shallow {
		args = append(args, "--depth=1")
	}
	if cfg.appendFilterArgs {
		args = appendFilterArgs(ctx, args)
	}

	args = append(args, target)

	switch cfg.mode {
	case fetchModeRef:
		args = append(args, fmt.Sprintf("+%s:%s", cfg.sourceRef, cfg.destinationRef))
	case fetchModeBlobs:
		for _, h := range cfg.hashes {
			args = append(args, h.String())
		}
	}

	return args
}

func (f *Fetcher) postFetch(ctx context.Context, cfg fetchConfig) error {
	if cfg.promoteToRef != "" {
		return f.promoteFetchedRef(ctx, cfg.destinationRef, cfg.promoteToRef, cfg.promoteLabel)
	}
	if cfg.advanceLocalRef == "" {
		return nil
	}

	repo, err := f.openRepo(ctx)
	if err != nil {
		return fmt.Errorf("open repository: %w", err)
	}

	fetchedRef, err := repo.Reference(cfg.destinationRef, true)
	if err != nil {
		return fmt.Errorf("read fetched ref %s: %w", cfg.destinationRef, err)
	}

	if err := f.advanceLocalRef(ctx, repo, cfg.advanceLocalRef, fetchedRef.Hash()); err != nil {
		return fmt.Errorf("advance local ref %s: %w", cfg.advanceLocalRef, err)
	}

	return nil
}

func (c fetchConfig) extraEnv() []string {
	if !c.disablePrompt {
		return nil
	}
	return []string{"GIT_TERMINAL_PROMPT=0"}
}

func formatFetchError(ctx context.Context, cfg fetchConfig, target string, output []byte, fetchErr error) error {
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return fmt.Errorf("fetch %s timed out after %s", cfg.errorLabel(), cfg.timeout)
	}

	redactedTarget := strategy.RedactURL(target)
	message := strings.TrimSpace(strings.ReplaceAll(string(output), target, redactedTarget))
	if message != "" {
		return fmt.Errorf("fetch %s from %s failed: %s: %w", cfg.errorLabel(), redactedTarget, message, fetchErr)
	}
	return fmt.Errorf("fetch %s from %s failed: %w", cfg.errorLabel(), redactedTarget, fetchErr)
}

func defaultRunGit(ctx context.Context, target string, args []string, extraEnv []string) ([]byte, error) {
	cmd := strategy.CheckpointGitCommand(ctx, target, args...)
	if len(extraEnv) != 0 {
		if cmd.Env == nil {
			cmd.Env = os.Environ()
		}
		cmd.Env = append(cmd.Env, extraEnv...)
	}
	return cmd.CombinedOutput()
}

func defaultOpenRepository(context.Context) (*git.Repository, error) {
	return git.PlainOpenWithOptions(".", &git.PlainOpenOptions{DetectDotGit: true})
}

