	fetcher.openRepo = func(context.Context) (*git.Repository, error) {
		return repo, nil
	}
	fetcher.advanceLocalRef = func(_ context.Context, _ *git.Repository, ref plumbing.ReferenceName, hash plumbing.Hash) error {
		advancedRef = ref
		advancedHash = hash
		return nil
	}

	err = fetcher.Fetch(
		context.Background(),
		WithV1Metadata(),
		WithTreeOnly(),
		WithDestinationRef(destinationRef),
		WithAdvanceLocalRef(plumbing.NewBranchReferenceName(paths.MetadataBranchName)),
	)
	if err != nil {
		t.Fatalf("Fetch() error = %v", err)
	}

	wantArgs := []string{
		"fetch",
		"--no-tags",
		"--depth=1",
		"origin",
		"+refs/heads/" + paths.MetadataBranchName + ":" + destinationRef.String(),
	}
	if len(gotArgs) != len(wantArgs) {
		t.Fatalf("args len = %d, want %d (%v)", len(gotArgs), len(wantArgs), gotArgs)
	}
	for i := range wantArgs {
		if gotArgs[i] != wantArgs[i] {
			t.Fatalf("args[%d] = %q, want %q", i, gotArgs[i], wantArgs[i])
