package remote

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// Option configures a Remote.
type Option func(*Remote) error

// Remote is a concrete checkpoint remote endpoint.
type Remote struct {
	url   string
	token string
}

// New creates a Remote from options.
func New(opts ...Option) (*Remote, error) {
	r := &Remote{}
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		if err := opt(r); err != nil {
			return nil, err
		}
	}
	if strings.TrimSpace(r.url) == "" {
		return nil, errors.New("remote URL is required")
	}
	return r, nil
}

// WithURL sets the remote URL.
func WithURL(rawURL string) Option {
	return func(r *Remote) error {
		if strings.TrimSpace(rawURL) == "" {
			return errors.New("remote URL cannot be empty")
		}
		r.url = rawURL
		return nil
	}
}

// WithToken sets the authentication token used for HTTPS git operations.
func WithToken(token string) Option {
	return func(r *Remote) error {
		if !isValidToken(token) {
			return errors.New("remote token contains invalid control characters")
		}
		r.token = token
		return nil
	}
}

// URL returns the configured remote URL.
func (r *Remote) URL() string {
	if r == nil {
		return ""
	}
	return r.url
}

// Fetch runs `git fetch --no-tags <url> <refspec...>` in the current repository.
func (r *Remote) Fetch(ctx context.Context, refspecs ...string) error {
	if r == nil {
		return errors.New("remote is nil")
	}
	if strings.TrimSpace(r.url) == "" {
		return errors.New("remote URL is required")
	}
	if len(refspecs) == 0 {
		return errors.New("at least one refspec is required")
	}

	args := []string{"fetch", "--no-tags", r.url}
	args = append(args, refspecs...)

	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Stdin = nil
	if protocol := protocolFromURL(r.url); protocol == protocolHTTPS && r.token != "" {
		cmd.Env = appendCheckpointTokenEnv(os.Environ(), r.token)
	}

	output, err := cmd.CombinedOutput()
	if err != nil {
		redactedURL := redactURL(r.url)
		msg := strings.TrimSpace(strings.ReplaceAll(string(output), r.url, redactedURL))
		if msg != "" {
			return fmt.Errorf("git fetch from %s failed: %s: %w", redactedURL, msg, err)
		}
		return fmt.Errorf("git fetch from %s failed: %w", redactedURL, err)
	}

	return nil
}

const protocolHTTPS = "https"

func protocolFromURL(rawURL string) string {
	switch {
	case strings.HasPrefix(rawURL, "https://"):
		return protocolHTTPS
	case strings.Contains(rawURL, "://"):
		return strings.SplitN(rawURL, "://", 2)[0]
	default:
		return ""
	}
}

func isValidToken(token string) bool {
	for _, b := range []byte(token) {
		if b < 0x20 || b == 0x7F {
			return false
		}
	}
	return true
}

func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
	filtered := make([]string, 0, len(baseEnv)+3)
	for _, e := range baseEnv {
		if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") ||
			strings.HasPrefix(e, "GIT_CONFIG_KEY_") ||
			strings.HasPrefix(e, "GIT_CONFIG_VALUE_") {
			continue
		}
		filtered = append(filtered, e)
	}
	encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
	return append(filtered,
		"GIT_CONFIG_COUNT=1",
		"GIT_CONFIG_KEY_0=http.extraHeader",
		"GIT_CONFIG_VALUE_0=Authorization: Basic "+encoded,
	)
}
package remote

import (
	"context"
	"fmt"
	"net/url"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const originRemote = "origin"
const checkpointTokenEnvVar = "ENTIRE_CHECKPOINT_TOKEN"

type gitRemoteInfo struct {
	protocol string
	host     string
}

// ResolveURL returns the effective checkpoint fetch URL for the current repository.
// If strategy_options.checkpoint_remote is configured, the returned URL is derived
// from the origin remote's protocol/host and the configured checkpoint repo.
// Otherwise, the origin remote URL is returned directly.
func ResolveURL(ctx context.Context) (string, error) {
	originURL, err := getRemoteURL(ctx, originRemote)
	if err != nil {
		return "", err
	}

	s, err := settings.Load(ctx)
	if err != nil {
		return "", fmt.Errorf("load settings: %w", err)
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return originURL, nil
	}

	info, err := parseGitRemoteURL(originURL)
	if err != nil {
		return "", fmt.Errorf("parse origin remote URL: %w", err)
	}
	if strings.TrimSpace(os.Getenv(checkpointTokenEnvVar)) != "" {
		info = &gitRemoteInfo{
			protocol: protocolHTTPS,
			host:     info.host,
		}
	}

	checkpointURL, err := deriveCheckpointURLFromInfo(info, config)
	if err != nil {
		return "", fmt.Errorf("derive checkpoint remote URL: %w", err)
	}

	return checkpointURL, nil
}

func getRemoteURL(ctx context.Context, remoteName string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "remote", "get-url", remoteName)
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("remote %q not found", remoteName)
	}
	return strings.TrimSpace(string(output)), nil
}

func parseGitRemoteURL(rawURL string) (*gitRemoteInfo, error) {
	rawURL = strings.TrimSpace(rawURL)

	if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
		parts := strings.SplitN(rawURL, ":", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid SSH URL: %s", redactURL(rawURL))
		}

		hostPart := parts[0]
		host := hostPart
		if idx := strings.Index(hostPart, "@"); idx >= 0 {
			host = hostPart[idx+1:]
		}

		pathPart := strings.TrimSuffix(parts[1], ".git")
		if !strings.Contains(pathPart, "/") {
			return nil, fmt.Errorf("cannot parse owner/repo from path: %s", pathPart)
		}

		return &gitRemoteInfo{protocol: "ssh", host: host}, nil
	}

	u, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL: %s", redactURL(rawURL))
	}
	if u.Scheme == "" {
		return nil, fmt.Errorf("no protocol in URL: %s", redactURL(rawURL))
	}

	return &gitRemoteInfo{protocol: u.Scheme, host: u.Hostname()}, nil
}

func deriveCheckpointURLFromInfo(info *gitRemoteInfo, config *settings.CheckpointRemoteConfig) (string, error) {
	switch info.protocol {
	case "ssh":
		return fmt.Sprintf("git@%s:%s.git", info.host, config.Repo), nil
	case protocolHTTPS:
		return fmt.Sprintf("https://%s/%s.git", info.host, config.Repo), nil
	default:
		return "", fmt.Errorf("unsupported protocol %q in origin remote", info.protocol)
	}
}

func redactURL(rawURL string) string {
	u, err := url.Parse(rawURL)
	if err != nil {
		if idx := strings.Index(rawURL, "@"); idx >= 0 {
			if colonIdx := strings.Index(rawURL[idx:], ":"); colonIdx >= 0 {
				return rawURL[idx+1:idx+colonIdx] + ":***"
			}
		}
		return "<unparseable>"
	}
	u.User = nil
	u.RawQuery = ""
	return u.Scheme + "://" + u.Host + u.Path
}

