func FetchURL(ctx context.Context) (string, error) {
	originURL, err := getRemoteURL(ctx, originRemote)
	if err != nil {
		return "", err
	}

	s, err := settings.Load(ctx)
	if err != nil {
		return "", fmt.Errorf("load settings: %w", err)
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return originURL, nil
	}

	info, err := parseGitRemoteURL(originURL)
	if err != nil {
		return "", fmt.Errorf("parse origin remote URL: %w", err)
	}
	if strings.TrimSpace(os.Getenv(checkpointTokenEnvVar)) != "" {
		info = &gitRemoteInfo{
			protocol: protocolHTTPS,
			host:     info.host,
		}
	}

	checkpointURL, err := deriveCheckpointURLFromInfo(info, config)
	if err != nil {
		return "", fmt.Errorf("derive checkpoint remote URL: %w", err)
	}

	return checkpointURL, nil
}

