		if idx := strings.Index(hostPart, "@"); idx >= 0 {
			host = hostPart[idx+1:]
		}

		pathPart := strings.TrimSuffix(parts[1], ".git")
		owner, _, err := splitOwnerRepo(pathPart)
		if err != nil {
			return nil, err
		}

		return &gitRemoteInfo{protocol: "ssh", host: host, owner: owner}, nil
	}

