		if idx := strings.Index(hostPart, "@"); idx >= 0 {
			host = hostPart[idx+1:]
		}

		pathPart := strings.TrimSuffix(parts[1], ".git")
		owner, repo, err := splitOwnerRepo(pathPart)
		if err != nil {
